ObjectActor* native_char_ai_actor(std::uintptr_t character) {
 for(auto& group:object_groups)for(auto& actor:group.instances)
  if(actor.identity==character)return &actor;
 return nullptr;
}
dh2::character_ai_queue_owner_v1::OwnerProjection native_char_ai_owner(
        const NativeCharAIProjection& projection) {
 auto* actor=native_char_ai_actor(projection.character_identity);
 if(!actor&&projection.character_identity!=prince_character.identity()&&
    !projection.authored_faery)
  throw std::runtime_error("Native CharAI owner Character is not retained");
 const auto& state=projection.state;
 auto forced=std::uint8_t((state.word_08>>8)&0xff),locked=std::uint8_t(state.word_08&0xff);
 // +8 is CharAI's aggro-delay countdown, never the Character controller.
 // SpawnOwner retains the real per-Character controller bytes when available.
 if(actor&&!native_source_controller_gates(*actor,forced,locked))
  throw std::runtime_error("Native CharAI controller projection owner mismatch");
 return {projection.character_identity,forced,locked,
  actor?actor->visible_80:(projection.authored_faery?projection.owner_visible:std::uint8_t(1)),
  actor?actor->zoning_enabled_2ee:(projection.authored_faery?projection.owner_zoning_enabled:std::uint8_t(0)),
  actor?actor->in_zone_2f0:(projection.authored_faery?projection.owner_in_zone:std::uint8_t(0))};
}
std::int32_t native_char_ai_queue_query(void*,dh2::character_ai_queue::State*,
        dh2::character_ai_queue::Entry* entry,
        const dh2::character_ai_queue::Request* request,std::uint32_t* output) {
 using Operation=dh2::character_ai_queue::Operation;
 using Classification=dh2::character_ai_classification::Query;
 if(!entry||!entry->owner||!request||!output||request->subject!=entry->owner->identity)return 1;
 const auto found=source_char_ai.by_character.find(request->subject);
 if(found==source_char_ai.by_character.end()||!found->second||found->second->ai_identity!=entry->ai)return 1;
 if(request->operation==Operation::is_zonable) {
  if(request->subject==prince_character.identity()) {
   const dh2::player_character_zonability_v1::Owner player{request->subject};
   dh2::player_character_zonability_v1::Result result{};
   if(dh2::player_character_zonability_v1::evaluate(&player,&result)!=
      dh2::player_character_zonability_v1::Status::complete)return 1;
   *output=result.zonable;return 0;
  }
  if(found->second->authored_faery){*output=found->second->updates_enabled;return 0;}
  auto* actor=native_char_ai_actor(request->subject);if(!actor)return 1;
  try {*output=native_actor_zonability(*actor);return 0;}catch(...) {return 1;}
 }
 auto* actor=native_char_ai_actor(request->subject);
 if(!actor&&request->subject!=prince_character.identity()&&
    !found->second->authored_faery)return 1;
 Classification query;
 if(request->operation==Operation::is_faerie)query=Classification::faerie;
 else if(request->operation==Operation::is_follower)query=Classification::follower;
 else return 1;
 if(found->second->authored_faery){*output=query==Classification::faerie;return 0;}
 if(!actor){*output=0;return 0;}
 try {*output=native_character_classification(*actor,query);return 0;}catch(...) {return 1;}
}
std::int32_t native_char_ai_turn_query(void*,dh2::character_ai_turn::State* state,
        dh2::character_ai_turn::Query query,std::uintptr_t owner,std::uint32_t* output) {
 using TurnQuery=dh2::character_ai_turn::Query;
 using Classification=dh2::character_ai_classification::Query;
 if(!state||!output||state->owner!=owner)return 1;
 const auto found=source_char_ai.by_character.find(owner);
 if(found==source_char_ai.by_character.end()||!found->second||found->second->ai_identity!=state->ai)return 1;
 if(query==TurnQuery::virtual_is_player) {
  *output=owner==prince_character.identity();return 0;
 }
 auto* actor=native_char_ai_actor(owner);
 if(!actor&&owner!=prince_character.identity()&&!found->second->authored_faery)return 1;
 if(!actor){
  *output=found->second->authored_faery&&query==TurnQuery::is_faerie;
  return 0;
 }
 try {
  *output=native_character_classification(*actor,
      query==TurnQuery::is_follower?Classification::follower:Classification::faerie);
  return 0;
 }catch(...) {return 1;}
}
bool native_char_ai_has_turn(ObjectActor& actor) {
 const auto found=source_char_ai.by_character.find(actor.identity);
 if(found==source_char_ai.by_character.end()||!found->second)
  throw std::runtime_error("Native Character AI turn owner is missing");
 const auto& projection=*found->second;
 const auto refreshed=source_char_ai_queue.refresh_owner(projection.ai_identity,
     native_char_ai_owner(projection));
 if(refreshed!=dh2::character_ai_queue_owner_v1::Status::complete)
  throw std::runtime_error("Native Character AI turn owner refresh failed");
 dh2::character_ai_turn::State state{projection.ai_identity,actor.identity};
 const auto globals=source_char_ai_queue.turn_globals();
 const dh2::character_ai_turn::Services services{nullptr,native_char_ai_turn_query};
 dh2::character_ai_turn::Result result{};
 if(dh2::character_ai_turn::evaluate(&state,&globals,&services,&result)!=
    dh2::character_ai_turn::Status::complete)
  throw std::runtime_error("Source CharAI IsMyTurn projection failed");
 return result.value!=0;
}
void advance_native_char_ai_queue(std::uint32_t dt_ms) {
 for(const auto& projection:source_char_ai.projections) {
  if(!projection)throw std::runtime_error("Null retained CharAI projection");
  if(source_char_ai_queue.refresh_owner(projection->ai_identity,
       native_char_ai_owner(*projection))!=dh2::character_ai_queue_owner_v1::Status::complete)
   throw std::runtime_error("Source CharAI owner refresh failed before Level update");
 }
 const dh2::character_ai_queue_owner_v1::Services services{nullptr,native_char_ai_queue_query};
 dh2::character_ai_queue_owner_v1::Result result{};
 if(source_char_ai_queue.advance(dt_ms,controller_global_blocked!=0,&services,&result)!=
    dh2::character_ai_queue_owner_v1::Status::complete)
  throw std::runtime_error("Source CharAI update queue advance failed");
}

std::int32_t NativeCryptRoomRuntime::initialize_zone_position(
        void*,const dh2::module_room_zone_bounds::Request* request) {
 if(!request||request->operation!=dh2::module_room_zone_bounds::Operation::set_position||
    !request->room_zone||!request->update_position)return 1;
 // The selected native renderer has no native Zone allocation. The portable
 // RoomZone owner applies the verified SetPosition/AABB field composition.
 return 0;
}

std::int32_t NativeCryptRoomRuntime::enroll_service(
        void* context,const dh2::room_zone_enrollment::Request* request,
        std::uint32_t* value) {
 auto* self=static_cast<NativeCryptRoomRuntime*>(context);
 if(!self||!request||!value)return 1;
 if(request->object==self->player_identity&&
    request->operation==dh2::room_zone_enrollment::Operation::is_zonable) {
  *value=0; // Character::IsZonable rejects Player before reading position.
  return 0;
 }
 const auto faery=std::find_if(self->faeries.begin(),self->faeries.end(),
     [&](const auto& item){return item.identity==request->object&&item.constructed;});
 if(faery!=self->faeries.end()&&
    request->operation==dh2::room_zone_enrollment::Operation::is_zonable) {
  *value=0; // IDA: Character::IsZonable returns false for IsFaerie.
  return 0;
 }
 const auto found=self->actors.find(request->object);
 if(found==self->actors.end()||!found->second)return 1;
 auto& actor=*found->second;
 switch(request->operation) {
 case dh2::room_zone_enrollment::Operation::is_zonable:
  try {*value=native_actor_zonability(actor);return 0;}catch(...){return 1;}
 case dh2::room_zone_enrollment::Operation::remove_from_room:
 case dh2::room_zone_enrollment::Operation::append_to_room:
  // The RoomZone owner wraps this callback and commits the member-node change
  // only after it succeeds, preserving the source callback/list order.
  return request->room_zone?0:1;
 case dh2::room_zone_enrollment::Operation::sync_visibility:
  if(request->auxiliary!=actor.visual_object_2d8)return 1;
  try {
   const bool zonable=native_actor_zonability(actor);
   actor.renderer_visible=actor.visible_80!=0&&
       !(zonable&&actor.zoning_enabled_2ee&&actor.in_zone_2f0==0);
  } catch(...) { return 1; }
  return 0;
 case dh2::room_zone_enrollment::Operation::zone_state_callback:
  actor.source_updates_enabled=request->value!=0;
  return 0;
 }
 return 1;
}

std::int32_t NativeCryptRoomRuntime::transition_service(
        void* context,const dh2::crypt_room_zone_owner_v1::TransitionRequest* request,
        std::uint32_t* value) {
 auto* self=static_cast<NativeCryptRoomRuntime*>(context);
 if(!self||!request||!request->room_zone)return 1;
 using Operation=dh2::crypt_room_zone_owner_v1::TransitionOperation;
 if(request->operation==Operation::query_module_visited||
    request->operation==Operation::set_module_visited) {
  if(!self->module_owner)return 1;
  auto found=std::find_if(self->module_owner->modules.begin(),
      self->module_owner->modules.end(),[&](const auto& module){
       return module.module_index==request->module_index;
      });
  if(found==self->module_owner->modules.end())return 1;
  if(request->operation==Operation::query_module_visited) {
   if(!value)return 1;
   *value=found->visited;return 0;
  }
  found->visited=1;return 0;
 }
 if(request->operation==Operation::zone_entered||
    request->operation==Operation::zone_exited) {
  const auto found=self->manager.find_by_identity(request->actor);
  if(!found)return 1;
  auto object=found->enrollment_view();
  const dh2::room_zone_enrollment::Services services{
      self,&NativeCryptRoomRuntime::enroll_service};
  dh2::room_zone_enrollment::Result result{};
  const auto status=request->operation==Operation::zone_entered
      ?dh2::room_zone_enrollment::zone_entered(&object,&services,&result)
      :dh2::room_zone_enrollment::zone_exited(&object,&services,&result);
  return status==dh2::room_zone_enrollment::Status::complete?0:1;
 }
 if(request->actor)return 1;
 bool changed=false;
 if(request->operation==Operation::add_room_object) {
  return self->manager.add_room_object(request->room_zone,&changed)==
             dh2::object_manager_runtime_owner_v1::Status::ok&&changed?0:1;
 }
 if(request->operation==Operation::remove_room_object) {
  return self->manager.remove_room_object(request->room_zone,&changed)==
             dh2::object_manager_runtime_owner_v1::Status::ok?0:1;
 }
 return 1;
}

bool NativeCryptRoomRuntime::update_frustum(
    const std::array<float,3>& player_position) {
 if(!room_zones_enabled) {
  manager.reset_visible_room_zone_count();
  return true;
 }
 std::uint32_t planes[6][4]{};
 for(unsigned plane=0;plane<6;++plane)
  for(unsigned component=0;component<4;++component)
   planes[plane][component]=source_camera.frustum.planes[plane][component];
 const dh2::crypt_room_zone_owner_v1::UpdateServices services{
     this,&NativeCryptRoomRuntime::transition_service};
 dh2::crypt_room_zone_owner_v1::UpdateResult result{};
 const auto status=zones.update_frustum(planes,player_position.data(),&services,&result);
 if(status!=dh2::crypt_room_zone_owner_v1::Status::complete) {
  __android_log_print(ANDROID_LOG_ERROR,"DH2Native",
      "Crypt RoomZone frustum update failed | status %s | module %u | operation %u",
      dh2::crypt_room_zone_owner_v1::status_name(status),result.failed_module_index,
      unsigned(result.failed_operation));
  return false;
 }
 manager.reset_visible_room_zone_count();
 for(std::uint32_t i=0;i<result.zones_visible;++i)manager.add_visible_room_zone();
 return true;
}

bool NativeCryptRoomRuntime::prepare_authored_faeries(
    const std::vector<dh2::world::GeneratedCryptFaerySourceV1>& descriptors,
    std::string& error) {
 error.clear();
 faeries.clear();
 faeries.reserve(descriptors.size());
 std::set<dh2::object_manager_runtime_owner_v1::SourceHandle> handles;
 for(const auto& descriptor:descriptors) {
  const auto factory=dh2::object_creation_map_v1::resolve(
      descriptor.object_type.c_str());
  if(factory.status!=dh2::object_creation_map_v1::Status::resolved||
     !factory.entry||factory.entry->constructor!=
        dh2::object_creation_map_v1::Constructor::character||
     descriptor.source_handle<4||descriptor.ai_table_id<0||
     std::size_t(descriptor.ai_table_id)>=actor_ai_tables.rows.size()||
     actor_ai_tables.rows[std::size_t(descriptor.ai_table_id)].type!=3||
     descriptor.character.empty()||descriptor.template_name!="Faery") {
   error="Generated Crypt Faery source type/factory, source key/name, or CharType=3 AI row is invalid";
   faeries.clear();return false;
  }
  if(!handles.insert(descriptor.source_handle).second||
     manager.find_by_source_handle(descriptor.source_handle)) {
   error="Generated Crypt Faery source handle collides with an existing ObjectManager entry";
   faeries.clear();return false;
  }
  faeries.emplace_back();
  auto& owner=faeries.back();
  owner.source=descriptor;
  const auto character_row=std::find(actor_character_names.begin(),
      actor_character_names.end(),descriptor.character);
  if(character_row==actor_character_names.end()||
     actor_character_property_rows.size()!=actor_character_names.size()) {
   error="Generated Crypt Faery CharacterTable row is not retained";
   faeries.clear();return false;
  }
  owner.character_table_row=static_cast<std::int32_t>(
      character_row-actor_character_names.begin());
  const auto& base=actor_character_property_rows[
      static_cast<std::size_t>(owner.character_table_row)];
  dh2::data::reset_properties(actor_property_rules,owner.properties,&base);
  if(!dh2::data::recalc_properties_with_class(actor_class_tables,
       actor_property_rules,owner.properties,error)) {
   error="Generated Crypt Faery Character::InitPost property prefix failed: "+error;
   faeries.clear();return false;
  }
  if(owner.properties.resolved[1]!=descriptor.ai_table_id) {
   error="Generated Crypt Faery descriptor AI id differs from its canonical Character properties";
   faeries.clear();return false;
  }
  owner.properties_ready=true;
  std::copy_n(descriptor.authored_world_transform,3,owner.visual_position.begin());
  const float half=3.14159265358979323846f/360.f;
  const float rx=descriptor.authored_world_transform[3]*half;
  const float ry=descriptor.authored_world_transform[4]*half;
  const float rz=descriptor.authored_world_transform[5]*half;
  const float sx=std::sin(rx),cx=std::cos(rx),sy=std::sin(ry),cy=std::cos(ry),
              sz=std::sin(rz),cz=std::cos(rz);
  owner.visual_rotation={sx*cy*cz-cx*sy*sz,cx*sy*cz+sx*cy*sz,
                         cx*cy*sz-sx*sy*cz,cx*cy*cz+sx*sy*sz};
  std::copy_n(descriptor.authored_world_transform+6,3,owner.visual_scale.begin());
  // The authored MGP world transform seeds this render-local pose only. The
  // canonical ObjectManager/Character projections are created by the source
  // Character factory after all constructor components succeed.
 }
 return true;
}

int NativeCryptRoomRuntime::faery_component(
    void* raw,dh2::character_constructor_owner_v1::Component component,
    dh2::character_constructor_owner_v1::Identity identity,
    dh2::character_runtime_factory_v1::ComponentStorage::Slot* slot,
    std::string& error) {
 using Component=dh2::character_constructor_owner_v1::Component;
 auto* owner=static_cast<AuthoredCryptFaeryOwner*>(raw);
 if(!owner||!slot||!slot->character_record||!identity) {
  error="Authored Faery component provider lacks the factory Record/slot";
  return 1;
 }
 auto* record=slot->character_record;
 if(record->character.identity!=identity||record->game_object.identity!=identity) {
  error="Authored Faery component identity differs from the canonical factory Record";
  return 1;
 }
 if(owner->record&&owner->record!=record) {
  error="Authored Faery component provider was rebound to a different Record";
  return 1;
 }
 owner->record=record;
 owner->identity=identity;
 switch(component) {
 case Component::game_object:
  slot->canonical_owner=&record->game_object;return 0;
 case Component::controllable:
  owner->controllable={identity,0};
  slot->canonical_owner=&owner->controllable;return 0;
 case Component::ai:
  if(!construct_authored_faery_char_ai(*owner,error))return 1;
  if(!owner->native_ai||owner->native_ai->character_identity!=identity||
     owner->native_ai->state.owner_04!=identity) {
   error="Authored Faery CharAI provider did not retain the factory Character identity";
   return 1;
  }
  slot->canonical_owner=&owner->native_ai->state;return 0;
 case Component::animator:
  // The existing per-Character Faery visual facade is the one mutable pose
  // owner. Immutable BDAE data is selected later and is not copied here.
  slot->canonical_owner=&record->faery_visual;return 0;
 case Component::properties:
  slot->canonical_owner=&owner->properties;return 0;
 case Component::controller:
  owner->controller={reinterpret_cast<std::uintptr_t>(&owner->controller),
                     identity,
                     reinterpret_cast<std::uintptr_t>(&owner->controllable),
                     0,0};
  owner->controllable.controller=owner->controller.identity;
  slot->canonical_owner=&owner->controller;return 0;
 default:
  error="Authored Faery component is not provided by its canonical owner";
  return 1;
 }
}

int NativeCryptRoomRuntime::faery_associate(
    void* raw,dh2::character_constructor_owner_v1::Association association,
    dh2::character_constructor_owner_v1::Identity identity,
    const dh2::character_runtime_factory_v1::ComponentStorage& components,
    std::string& error) {
 using Association=dh2::character_constructor_owner_v1::Association;
 auto* owner=static_cast<AuthoredCryptFaeryOwner*>(raw);
 auto* record=owner?owner->record:nullptr;
 if(!record||identity!=owner->identity||record->character.identity!=identity) {
  error="Authored Faery association does not match its canonical factory Record";
  return 1;
 }
 switch(association) {
 case Association::target_list:
  // The Character's aggro GameObject is already embedded in this same Record;
  // the ObjectManager/CharacterList roster is enrolled after factory Add.
  return record->character.object==&record->aggro_object?0:1;
 case Association::controller:
  if(!owner->controller.identity||owner->controller.character!=identity||
     owner->controllable.character!=identity||
     owner->controllable.controller!=owner->controller.identity) {
   error="Authored Faery default controller is not attached to its Character controllable";
   return 1;
  }
  return 0;
 case Association::timers:
  if(!record->coordinator||record->coordinator->owner()!=identity)break;
  return 0;
 case Association::ai:
  if(owner->native_ai&&owner->native_ai->state.owner_04==identity&&
     components.find(dh2::character_constructor_owner_v1::Component::ai)==
       &owner->native_ai->state)return 0;
  break;
 case Association::animator:
  if(components.find(dh2::character_constructor_owner_v1::Component::animator)==
       &record->faery_visual)return 0;
  break;
 case Association::state_machine:
  if(record->coordinator&&record->coordinator->owner()==identity&&
     components.find(dh2::character_constructor_owner_v1::Component::state_machine)==
       record->coordinator.get())return 0;
  break;
 case Association::properties:
  if(components.find(dh2::character_constructor_owner_v1::Component::properties)==
       &owner->properties)return 0;
  break;
 }
 error="Authored Faery Character association lacks its same-Record component owner";
 return 1;
}

int NativeCryptRoomRuntime::faery_register_state(
    void* raw,dh2::character_constructor_owner_v1::Identity identity,
    std::uint32_t state,std::string& error) {
 auto* owner=static_cast<AuthoredCryptFaeryOwner*>(raw);
 if(!owner||!owner->record||owner->identity!=identity||state>=20||
    !owner->record->coordinator||owner->record->coordinator->owner()!=identity) {
  error="Authored Faery Character RegisterState lacks its canonical Coordinator";
  return 1;
 }
 // Coordinator owns the native FSM state; the factory's constructor receipt
 // retains the source's exact 0..19 RegisterState calls and rollback order.
 return 0;
}

void NativeCryptRoomRuntime::faery_rollback(
    void* raw,dh2::character_constructor_owner_v1::Action action,
    std::uint32_t value,dh2::character_constructor_owner_v1::Identity identity,
    dh2::character_runtime_factory_v1::ComponentStorage&) noexcept {
 auto* owner=static_cast<AuthoredCryptFaeryOwner*>(raw);
 if(!owner||owner->identity!=identity||
    action!=dh2::character_constructor_owner_v1::Action::component)return;
 const auto component=static_cast<dh2::character_constructor_owner_v1::Component>(value);
 if(component==dh2::character_constructor_owner_v1::Component::ai)
  (void)retire_authored_faery_char_ai(*owner);
 else if(component==dh2::character_constructor_owner_v1::Component::controller)
  owner->controller={};
 else if(component==dh2::character_constructor_owner_v1::Component::controllable)
  owner->controllable={};
}

bool NativeCryptRoomRuntime::construct_faery_after_factory(
    AuthoredCryptFaeryOwner& owner,std::string& error) {
 error.clear();
 if(owner.constructed||owner.registered){error="Generated Crypt Faery is already constructed";return false;}
 const auto factory=dh2::object_creation_map_v1::resolve(
     owner.source.object_type.c_str());
 if(!owner.properties_ready||factory.status!=
      dh2::object_creation_map_v1::Status::resolved||!factory.entry||
    factory.entry->constructor!=dh2::object_creation_map_v1::Constructor::character||
    owner.source.template_name!="Faery"||
    owner.source.ai_table_id<0||
    std::size_t(owner.source.ai_table_id)>=actor_ai_tables.rows.size()||
    actor_ai_tables.rows[std::size_t(owner.source.ai_table_id)].type!=3||
    !source_char_ai.ready) {
  error="Generated Crypt Faery factory facts or shared CharAI owner are incomplete";
  return false;
 }
 if(!character_factory) {
  try {
   character_factory=std::make_unique<dh2::character_runtime_factory_v1::Owner>(
       manager,dh2::native::character_list::factory_services(native_characters));
  } catch(...) {
   error="Canonical Character factory owner allocation failed";return false;
  }
 }
 namespace Factory=dh2::character_runtime_factory_v1;
 const Factory::Services services{&owner,&NativeCryptRoomRuntime::faery_component,
     &NativeCryptRoomRuntime::faery_associate,
     &NativeCryptRoomRuntime::faery_register_state,
     &NativeCryptRoomRuntime::faery_rollback};
 dh2::object_manager_runtime_owner_v1::GameObject game_object{};
 game_object.source_handle=owner.source.source_handle;
 game_object.name=owner.source.name;
 game_object.world_x=owner.visual_position[0];
 game_object.world_y=owner.visual_position[1];
 game_object.zoning_enabled_2ee=1;
 game_object.visible_80=0;
 dh2::character::aggro_search::GameObject aggro_object{};
 std::copy(owner.visual_position.begin(),owner.visual_position.end(),
           aggro_object.position);
 std::copy(owner.visual_position.begin(),owner.visual_position.end(),
           aggro_object.target_position);
 aggro_object.visible=0;
 aggro_object.has_target_position=0;
 aggro_object.character_2ee=1;
 aggro_object.character_2f0=0;
 Factory::Record* record=nullptr;
 Factory::Result result{};
 const auto status=character_factory->create(owner.source.source_handle,
     game_object,aggro_object,services,&record,&result,error);
 if(status!=Factory::Status::complete||!record) {
  record=character_factory->find(owner.source.source_handle);
  if(record) {
   owner.record=record;
   owner.identity=record->character.identity;
   owner.constructed=record->constructor.constructor_complete;
   owner.registered=record->object_registered&&record->character_listed;
   source_handles.push_back(owner.source.source_handle);
  } else {
   owner.record=nullptr;
   owner.identity=0;
  }
  if(error.empty())error="Canonical Character factory rejected the authored Faery";
  return false;
 }
 owner.record=record;
 owner.identity=record->character.identity;
 owner.constructed=true;owner.registered=true;
 source_handles.push_back(owner.source.source_handle);
 if(record->constructor.identity!=owner.identity||
    record->game_object.identity!=owner.identity||
    record->character.object!=&record->aggro_object||
    !owner.native_ai||record->canonical_ai()!=&owner.native_ai->state) {
  error="Canonical Faery factory Record did not retain one Character/GameObject/CharAI owner";
  return false;
 }
 const auto controller_status=dh2::character_faery_controller_v1::bind(
     *record,reinterpret_cast<std::uintptr_t>(&owner.controller),
     reinterpret_cast<std::uintptr_t>(&owner.controllable),error);
 if(controller_status!=dh2::character_faery_controller_v1::Status::complete) {
  error="Canonical Faery controller component binding failed: "+error;
  return false;
 }
 owner.source_character_identity=owner.identity;
 record->character.source_word_1310=owner.properties.resolved[198];
 record->character.source_word_1314=owner.properties.resolved[199];
 record->source_model_name=owner.source.character;
 record->source_owner_scale=owner.visual_scale;
 record->game_object.visual_object_2d8=0;
 if(character_factory->mark_source_properties_ready(owner.source.source_handle,
       nullptr,error)!=Factory::Status::complete) {
  error="Canonical Character factory could not publish Faery source properties";
  return false;
 }
 return true;
}

bool NativeCryptRoomRuntime::initialize(
        dh2::crypt_module_bounds_registry_v1::Owner& module_bounds,
        const std::vector<ObjectActor*>& ordered_actors,Address player,
        const dh2::world::source_handle_ledger_v1::Ledger* source_ledger,
        bool use_source_room_zones,std::string& error) {
 error.clear();
 const auto source_module_count=source_ledger&&
     source_ledger->initial_top_level_handle_offset>0
       ?source_ledger->initial_top_level_handle_offset-1:0;
 if((use_source_room_zones&&module_bounds.modules.empty())||!player||!source_ledger||
    source_ledger->entries.empty()||source_ledger->first_source_handle!=4||
    (use_source_room_zones&&source_ledger->initial_top_level_handle_offset!=
        1+module_bounds.modules.size())||!source_module_count) {
  error="Source ObjectManager inputs are incomplete";return false;
 }
 try {
  room_zones_enabled=use_source_room_zones;
  module_owner=use_source_room_zones?&module_bounds:nullptr;
  player_identity=player;
  actors.reserve(ordered_actors.size());
  actor_records.reserve(ordered_actors.size());
  std::vector<dh2::world::GeneratedCryptFaerySourceV1> authored_faery_sources=
      active_generated_crypt_faery_sources;
  if(active_level_assets.name=="SWAMP"&&
     active_level_assets.level_file=="001_swamp.mlx") {
   for(const auto& source:active_level_assets.source_character_census) {
    if(source.template_name!="Faery")continue;
    if(source.duplicate_name||source.source_handle<0||source.name.empty()||
       source.character.empty()||!source.script.empty()) {
     error="SWAMP authored Faery row lacks a unique un-scripted Character owner";
     clear();return false;
    }
    const auto character=std::find(actor_character_names.begin(),
        actor_character_names.end(),source.character);
    const auto ai_field=std::find(actor_character_fields.begin(),
        actor_character_fields.end(),"AI");
    if(character==actor_character_names.end()||
       actor_character_property_rows.size()!=actor_character_names.size()||
       ai_field==actor_character_fields.end()) {
     error="SWAMP Faery CharacterTable AI property is not retained";
     clear();return false;
    }
    const auto ai_id=actor_character_property_rows[
        std::size_t(character-actor_character_names.begin())][
        std::size_t(ai_field-actor_character_fields.begin())];
    const auto* ai=dh2::data::ai_props(actor_ai_tables,ai_id);
    if(!ai||ai->type!=3) {
     error="SWAMP Faery source Character does not resolve to canonical CharType 3";
     clear();return false;
    }
    const auto duplicate=std::find_if(authored_faery_sources.begin(),
        authored_faery_sources.end(),[&](const auto& existing){
         return existing.source_handle==source.source_handle||
             (existing.module_index==source.module_index&&
              existing.source_record==source.source_record);
        });
    if(duplicate!=authored_faery_sources.end()) {
     error="SWAMP Faery source occurrence is already owned by the generated Faery set";
     clear();return false;
    }
    authored_faery_sources.emplace_back();
    auto& descriptor=authored_faery_sources.back();
    descriptor.module_index=source.module_index;
    descriptor.source_record=source.source_record;
    descriptor.source_handle=source.source_handle;
    descriptor.name=source.name;
    descriptor.object_type="Character";
    descriptor.template_name=source.template_name;
    descriptor.character=source.character;
    descriptor.ai_table_id=ai_id;
    std::copy(source.world.position.begin(),source.world.position.end(),
              descriptor.authored_world_transform);
    std::copy(source.world.rotation_degrees.begin(),
              source.world.rotation_degrees.end(),
              descriptor.authored_world_transform+3);
    std::copy(source.world.scale.begin(),source.world.scale.end(),
              descriptor.authored_world_transform+6);
   }
  }
  source_handles.reserve(ordered_actors.size()+1+
                         authored_faery_sources.size());
  for(auto* actor:ordered_actors) {
   if(!actor||actor->kind!=1||actor->identity==player_identity)continue;
   if(!actor->identity||actors.find(actor->identity)!=actors.end()) {
    error="Crypt RoomZone actor identity is invalid or duplicated";
    clear();return false;
   }
   if(actor->source_handle<0||actor->source_module_index>=source_module_count||
      actor->source_record==std::numeric_limits<std::uint32_t>::max()) {
    error="Source actor lacks retained ObjectManager source provenance";
    clear();return false;
   }
   actor_records.push_back(actor);
   actor->room_zone_2f4=0;actor->in_room_list_2ef=0;
   actor->zoning_enabled_2ee=1;actor->in_zone_2f0=0;actor->visible_80=1;
   actor->visual_object_2d8=actor->identity; // opaque renderer adapter token
   // SWAMP's source MLX has no RoomZone root and its MGPs have no RoomZone
   // objects. Do not synthesize one zone per Module; ordinary Characters
   // follow ObjectManager::InitPost's updatable-object list directly.
   actor->source_room_zone_managed=use_source_room_zones;
   actor->source_updates_enabled=!use_source_room_zones;
   actor->renderer_visible=true;
   // ObjectManager::Add publishes Character* into the +0x60 flat list as
   // part of the same successful Add transaction. Keep the DACT actor's
   // Character/GameObject views borrowed from its existing renderer owner.
   auto& actor_projection=actor->search_projection;
   actor_projection.object.identity=actor->identity;
   actor_projection.object.character_2ee=actor->zoning_enabled_2ee;
   actor_projection.object.character_2f0=actor->in_zone_2f0;
   actor_projection.object.visible=actor->visible_80;
   actor_projection.character.identity=actor->identity;
   actor_projection.character.object=&actor_projection.object;
   actor_projection.character.source_word_1310=actor->properties.resolved[198];
   actor_projection.character.source_word_1314=actor->properties.resolved[199];
   actor_projection.is_character=1;
   dh2::object_manager_runtime_owner_v1::GameObject projection{};
   projection.identity=actor->identity;
   projection.source_handle=actor->source_handle;
   // ObjectBase+100 is the source module ID consumed by
   // ObjectManager::GetObjectByName's final argument. Keep it on the shared
   // manager projection so authored callbacks use canonical name resolution.
   projection.module_id_64=actor->source_object_module_id;
   projection.global_87=actor->source_global_87;
   projection.world_x=actor->position[0];projection.world_y=actor->position[1];
   projection.zoning_enabled_2ee=actor->zoning_enabled_2ee;
   projection.visible_80=actor->visible_80;
   projection.visual_object_2d8=actor->visual_object_2d8;
   projection.bind_live_fields({&actor->position[0],&actor->position[1],
       &actor->room_zone_2f4,&actor->in_room_list_2ef,&actor->zoning_enabled_2ee,
       &actor->in_zone_2f0,&actor->visual_object_2d8,&actor->visible_80,
       &actor->source_object_module_id,&actor->source_global_87});
   const auto actor_entry=actors.emplace(actor->identity,actor);
   if(!actor_entry.second) {
    error="Source ObjectManager actor identity index failed";clear();return false;
   }
   dh2::native::character_roster_transaction::Result registration{};
   const auto add_status=dh2::native::character_roster_transaction::register_after_add(
       &manager,&native_characters,actor->source_handle,&projection,
       &actor_projection.character,false,&registration);
   if(add_status!=dh2::native::character_roster_transaction::Status::complete) {
    // Preserve an orphaned manager prefix for the normal clear path to retry.
    if(add_status==dh2::native::character_roster_transaction::Status::rollback_failed&&
       manager.find_by_source_handle(actor->source_handle))
     source_handles.push_back(actor->source_handle);
    else actors.erase(actor_entry.first);
    error="Source ObjectManager/Character-list actor transaction failed";
    clear();return false;
   }
   source_handles.push_back(actor->source_handle);
  }

  if(!prepare_authored_faeries(authored_faery_sources,error)) {
   error="Authored Faery owner preparation failed: "+error;
   clear();return false;
  }
  for(auto& faery:faeries) {
   __android_log_print(ANDROID_LOG_INFO,"DH2Native",
      "Authored Faery Character factory | %s | CharacterTable row %d | class %d | CharType 3 | source handle %d",
       faery.source.name.c_str(),faery.character_table_row,
       faery.properties.resolved[26],faery.source.source_handle);
   std::string construction_error;
   if(!construct_faery_after_factory(faery,construction_error)) {
    error="Generated Crypt Faery Character factory failed: "+construction_error;
    clear();return false;
   }
   __android_log_print(ANDROID_LOG_INFO,"DH2Native",
       "Generated Crypt Faery Character lifecycle prefix registered | %s | identity %zu | shared ObjectManager/CharacterList/CharAI | source factory, InitPost/Final, AISFaery, POFaerie and visual pending",
       faery.source.character.c_str(),std::size_t(faery.identity));
  }
  if(!faeries.empty())
   __android_log_print(ANDROID_LOG_INFO,"DH2Native",
       "Crypt Faery lifecycle-prefix checkpoint | authored %zu | roster prefixes registered %zu | source factory/InitPost/Final/AISFaery/POFaerie/visual pending",
       faeries.size(),std::size_t(std::count_if(faeries.begin(),faeries.end(),
           [](const auto& faery){return faery.registered;})));

  // PlayerManager keeps the player in ObjectManager's +0x60 map and the
  // distinct +0x88 no-room list. RoomZone's Character override rejects it.
  // MenuCharacterSelect::Show creates the preview Player as handle 3 after
  // the MainMenu flush and its LightPoint/AnimatedDecor allocations. The
  // same ObjectManager survives the traced Start Game path into Level::Load.
  constexpr auto player_handle=
      dh2::object_manager_runtime_owner_v1::SourceHandle{3};
  dh2::object_manager_runtime_owner_v1::GameObject player_projection{};
  player_projection.identity=player_identity;
  // XP range checks read the source GameObject's live world XY. Keep this
  // projection borrowed from the same actor runtime that advances the player;
  // a value snapshot here would go stale as soon as gameplay begins.
  player_projection.bind_live_fields({
      &prince_runtime.subobjects.position[0],
      &prince_runtime.subobjects.position[1]});
  prince_search_projection.object.identity=player_identity;
  prince_search_projection.character.identity=player_identity;
  prince_search_projection.character.object=&prince_search_projection.object;
  prince_search_projection.character.source_word_1310=prince_combat.properties.resolved[198];
  prince_search_projection.character.source_word_1314=prince_combat.properties.resolved[199];
  dh2::native::character_roster_transaction::Result roster_result{};
  const auto roster_status=
      dh2::native::character_roster_transaction::register_after_add(
          &manager,&native_characters,player_handle,&player_projection,
          &prince_search_projection.character,false,&roster_result);
  if(roster_status!=dh2::native::character_roster_transaction::Status::complete) {
   // A failed rollback is the only failure that can leave handle 3 committed.
   // Retire that partial map entry before rolling back the already-added actors.
   if(roster_status==dh2::native::character_roster_transaction::Status::rollback_failed) {
    bool removed=false;
    manager.remove_object(player_handle,&removed);
   }
   error="Crypt player ObjectManager/Character-list transaction failed";
   clear();return false;
  }
  source_handles.push_back(player_handle);
  bool player_added=false;
  if(manager.register_player_no_room(player_identity,&player_added)!=
       dh2::object_manager_runtime_owner_v1::Status::ok||!player_added) {
   error="Crypt Player no-room registration failed";clear();return false;
  }

  if(use_source_room_zones) {
   const dh2::module_room_zone_bounds::Services position_services{
       this,&NativeCryptRoomRuntime::initialize_zone_position};
   const dh2::room_zone_enrollment::Services enrollment_services{
       this,&NativeCryptRoomRuntime::enroll_service};
   dh2::crypt_room_zone_manager_bridge_v1::Result result{};
   const auto status=dh2::crypt_room_zone_manager_bridge_v1::initialize_object_lists(
       module_bounds,zones,manager,&position_services,&enrollment_services,&result);
   if(status!=dh2::crypt_room_zone_manager_bridge_v1::Status::complete) {
    error="Crypt RoomZone ObjectManager enrollment failed: ";
    error+=dh2::crypt_room_zone_manager_bridge_v1::status_name(status);
    clear();return false;
   }
  }
  if(active_level_assets.name=="SWAMP"&&
     active_level_assets.level_file=="001_swamp.mlx"&&
     !initialize_source_move_in_zones(error)) {
   error="SWAMP source QuestMoveInZone registration failed: "+error;
   clear();return false;
  }
  // ObjectBase's default IsUpdatable is false, while the Character class
  // inherits GameObject::IsUpdatable (0x38aac0), which returns true. These
  // are the complete Character rows this scoped Crypt manager has created;
  // publish their InitPost result in source-key order after all registrations.
  // Do not infer membership from renderer group or RoomZone order.
  dh2::object_manager_runtime_owner_v1::Owner::Cursor update_cursor{};
  manager.reset(&update_cursor);
  for(;;) {
   dh2::object_manager_runtime_owner_v1::GameObject* object=nullptr;
   if(manager.next(&update_cursor,&object)!=
      dh2::object_manager_runtime_owner_v1::Status::ok) {
    error="Source ObjectManager active Character traversal failed";
    clear();return false;
   }
   if(!object)break;
   std::size_t character_occurrences=0;
   const bool is_character=native_characters.contains_identity(
       object->identity,&character_occurrences);
   if(!is_character)continue;
   if(character_occurrences!=1) {
    error="Source ObjectManager Character is duplicated in the canonical CharacterList";
    clear();return false;
   }
   bool appended=false;
   const auto update_status=manager.append_init_post_update_object(
       object->identity,true,&appended);
   if(update_status!=dh2::object_manager_runtime_owner_v1::Status::ok||!appended) {
    error="Source ObjectManager failed to append an eligible Character to +0x2c";
    clear();return false;
   }
  }
  for(const auto& item:actors)if(item.second&&item.second->in_room_list_2ef)
   ++enrolled_characters;
  __android_log_print(ANDROID_LOG_INFO,"DH2Native",
      "Source Character registration | +0x2c %zu | RoomZones %zu | enrolled %u | player no-room %u | room-zone policy %u | other ObjectManager types pending",
      manager.update_object_count(),zones.zone_count(),enrolled_characters,
      unsigned(player_added),unsigned(room_zones_enabled));
  return true;
 } catch(const std::exception& exception) {
  error=std::string("Crypt RoomZone runtime failed: ")+exception.what();
 } catch(...) {
  error="Crypt RoomZone runtime failed";
 }
 clear();
 return false;
}

bool NativeCryptRoomRuntime::initialize_source_move_in_zones(
        std::string& error) {
 error.clear();
 const auto& sources=active_level_assets.source_move_in_zone_census;
 if(sources.empty())return true;
 if(active_level_assets.name!="SWAMP"||
    active_level_assets.level_file!="001_swamp.mlx"||sources.size()!=1) {
  error="SWAMP authored QuestMoveInZone census is not the single reviewed row";
  return false;
 }
 source_move_in_zones.reserve(sources.size());
 source_handles.reserve(source_handles.size()+sources.size());
 for(const auto& source:sources) {
  if(source.name!="_prim_WitchQuestStart"||
     source.gametype!="QuestMoveInZone"||
     source.template_name!="QuestMoveInZone"||source.module_index!=4||
     source.activate_condition!="IsBefore_Swamp_KillWitch"||
     !source.deactivate_condition.empty()||!source.dimensions.empty()||
     source.duplicate_name||source.source_handle<0||
     !active_level_assets.source_level_handle_ledger) {
   error="SWAMP QuestMoveInZone row differs from its exact MGP/ledger source contract";
   return false;
  }
  auto zone=std::make_unique<SourceMoveInZone>();
  zone->source=source;
  const float scale[3]={source.world.scale[0],source.world.scale[1],
                        source.world.scale[2]};
  // Property44's source default is (200,200,200). The generic MGP row census
  // retains authored transforms and conditions; the source Witch row has no
  // dimensions override, so this is the actual Zone::InitPost property value.
  const float dimensions[3]={200.f,200.f,200.f};
  if(dh2::level_world::quest_move_in_zone_collision_v1::build_init_post_local_aabb(
       scale,dimensions,zone->local_aabb_xyxy.data(),error)!=
       dh2::level_world::quest_move_in_zone_collision_v1::Status::complete)
   return false;
  bool activates=true,deactivates=false;
  if(!evaluate_source_zone_condition(source.activate_condition,true,activates,error)||
     !evaluate_source_zone_condition(source.deactivate_condition,false,deactivates,error))
   return false;
  zone->enabled=std::uint8_t(activates&&!deactivates);
  const auto identity=reinterpret_cast<Address>(zone.get());
  GameObject projection{};
  projection.identity=identity;
  projection.source_handle=source.source_handle;
  projection.module_id_64=std::int32_t(source.module_index);
  projection.world_x=source.world.position[0];
  projection.world_y=source.world.position[1];
  projection.zoning_enabled_2ee=1;
  projection.visible_80=zone->enabled;
  projection.visual_object_2d8=0;
  projection.bind_live_fields({&zone->source.world.position[0],
      &zone->source.world.position[1],nullptr,nullptr,nullptr,nullptr,nullptr,
      &zone->enabled,nullptr,nullptr});
  GameObject* stored=nullptr;
  if(manager.add_named_object(source.source_handle,source.name,projection,&stored)!=
         dh2::object_manager_runtime_owner_v1::Status::ok||!stored) {
   error="SWAMP QuestMoveInZone could not register at its canonical source handle";
   return false;
  }
  source_handles.push_back(source.source_handle);
  zone->object=stored;
  if(dh2::level_world::quest_move_in_zone_collision_v1::bind(
       manager,source.source_handle,-1,zone->bound,error)!=
       dh2::level_world::quest_move_in_zone_collision_v1::Status::complete)
   return false;
  source_move_in_zones.push_back(std::move(zone));
 }
 if(!reconcile_source_move_in_zone_conditions(error))return false;
 __android_log_print(ANDROID_LOG_INFO,"DH2Native",
     "SWAMP source QuestMoveInZone registered | exact MGP rows %zu | canonical ObjectManager handles | activate_cond evaluated through current Save/QEST",
     source_move_in_zones.size());
 return true;
}

bool NativeCryptRoomRuntime::reconcile_source_move_in_zone_conditions(
        std::string& error) {
 for(auto& zone:source_move_in_zones) {
  if(!zone||!zone->object||
     manager.find_by_identity(zone->object->identity)!=zone->object) {
   error="SWAMP QuestMoveInZone lost its canonical ObjectManager row";
   return false;
  }
  bool activates=true,deactivates=false;
  if(!evaluate_source_zone_condition(zone->source.activate_condition,true,
                                     activates,error)||
     !evaluate_source_zone_condition(zone->source.deactivate_condition,false,
                                     deactivates,error))return false;
  const auto enabled=std::uint8_t(activates&&!deactivates);
  zone->enabled=enabled;
  zone->object->visible_80=enabled;
  if(zone->object->live_fields.visible_80)
   *zone->object->live_fields.visible_80=enabled;
  if(enabled&&!zone->sensor.attached()) {
   MoveInZoneCollision::PhysicalSensor geometry{};
   if(MoveInZoneCollision::build_physical_sensor_from_aabb(
        zone->source.world.position.data(),zone->local_aabb_xyxy.data(),
        geometry,error)!=MoveInZoneCollision::Status::complete)return false;
   const MoveInZoneSensor::SensorServices sensor_services{
       this,&NativeCryptRoomRuntime::resolve_move_in_zone_peer,
       &NativeCryptRoomRuntime::move_in_zone_owners_enabled,
       &NativeCryptRoomRuntime::move_in_zone_source_collision_test};
   const MoveInZoneCollision::Services collision_services{
       this,&NativeCryptRoomRuntime::move_in_zone_virtual_24,
       &NativeCryptRoomRuntime::move_in_zone_current_level,
       &NativeCryptRoomRuntime::move_in_zone_constant,
       &NativeCryptRoomRuntime::raise_move_in_zone_event};
   if(zone->sensor.attach(actor_world,zone->bound,geometry,sensor_services,
                          collision_services,error)!=MoveInZoneSensor::Status::complete)
    return false;
  } else if(!enabled&&zone->sensor.attached()) {
   if(zone->sensor.detach(error)!=MoveInZoneSensor::Status::complete)return false;
  }
 }
 error.clear();return true;
}

bool NativeCryptRoomRuntime::detach_source_move_in_zones() noexcept {
 for(auto& zone:source_move_in_zones)if(zone) {
  std::string error;
  const auto status=zone->sensor.detach(error);
  if(status!=dh2::level_world::quest_move_in_zone_sensor_owner_v1::Status::complete&&
     status!=dh2::level_world::quest_move_in_zone_sensor_owner_v1::Status::world_retired)
   return false;
 }
 return true;
}

bool NativeCryptRoomRuntime::clear() noexcept {
 if(!detach_source_move_in_zones())return false;
 for(std::size_t index=0;index<zones.zone_count();++index) {
  dh2::crypt_room_zone_owner_v1::ZoneView zone{};
  while(zones.zone_at(index,&zone)&&zone.member_count) {
   const auto identity=zone.members[0];
   const auto status=zones.forget_source_unlinked_actor(zone.module_index,identity);
   if(status!=dh2::crypt_room_zone_owner_v1::Status::complete)return false;
   const auto actor=actors.find(identity);
   if(actor!=actors.end()&&actor->second) {
    actor->second->room_zone_2f4=0;actor->second->in_room_list_2ef=0;
    actor->second->in_zone_2f0=0;actor->second->source_updates_enabled=false;
   }
  }
  if(zones.zone_at(index,&zone)) {
   bool removed=false;
   if(manager.remove_room_object(zone.identity,&removed)!=
       dh2::object_manager_runtime_owner_v1::Status::ok)return false;
  }
 }
 if(zones.clear()!=dh2::crypt_room_zone_owner_v1::Status::complete)return false;
 for(auto* actor:actor_records)if(actor) {
  actor->source_room_zone_managed=false;
  actor->room_zone_2f4=0;actor->in_room_list_2ef=0;
  actor->in_zone_2f0=0;actor->source_updates_enabled=false;
  actor->renderer_visible=true;
 }
 bool removed=false;
 if(player_identity) {
  if(manager.remove_no_room_object(player_identity,&removed)!=
       dh2::object_manager_runtime_owner_v1::Status::ok)return false;
 }
 for(const auto handle:source_handles) {
  const auto faery=std::find_if(faeries.begin(),faeries.end(),[&](const auto& item){
   return item.source.source_handle==handle&&item.record;
  });
  if(faery!=faeries.end()) {
   if(!character_factory)return false;
   if(faery->record) {
    if(faery->record->faery_controller.navigation_ready) {
     if(!level.native_floor)return false;
     std::string navigation_error;
     const auto navigation_status=
         dh2::character_faery_controller_v1::retire_navigation(
             *faery->record,level.native_floor->collision_world,live_registry,
             navigation_error);
     if(navigation_status!=
         dh2::character_faery_controller_v1::Status::complete)return false;
    }
    std::string physical_error;
    const auto detached=dh2::character_faery_source_physical_owner_v1::detach(
        *faery->record,physical_error);
    if(detached!=dh2::character_faery_source_physical_owner_v1::Status::complete)
     return false;
    faery->physics=0;
   }
   dh2::character_runtime_factory_v1::Result result{};
   std::string error;
   const auto status=character_factory->retire(handle,&result,error);
   if(status!=dh2::character_runtime_factory_v1::Status::complete&&
      status!=dh2::character_runtime_factory_v1::Status::not_found)return false;
   faery->registered=false;
   faery->constructed=false;
   faery->record=nullptr;
   continue;
  }
  const auto actor=std::find_if(actor_records.begin(),actor_records.end(),
      [&](const auto* item){return item&&item->source_handle==handle;});
  if(actor!=actor_records.end()&&manager.find_by_source_handle(handle)) {
   std::size_t occurrences=0;
   const bool listed=native_characters.contains_identity((*actor)->identity,&occurrences);
   if(listed&&occurrences==1) {
    dh2::native::character_roster_transaction::Result result{};
    if(dh2::native::character_roster_transaction::remove_after_remove(
        &manager,&native_characters,handle,&(*actor)->search_projection.character,
        &result)!=dh2::native::character_roster_transaction::Status::complete)
     return false;
   } else if(!listed&&occurrences==0) {
    if(manager.remove_object(handle,&removed)!=
        dh2::object_manager_runtime_owner_v1::Status::ok)return false;
   } else return false;
  } else if(handle==3&&manager.find_by_source_handle(handle)) {
   dh2::native::character_roster_transaction::Result result{};
   if(dh2::native::character_roster_transaction::remove_after_remove(
       &manager,&native_characters,handle,&prince_search_projection.character,
       &result)!=dh2::native::character_roster_transaction::Status::complete)
    return false;
  } else {
   if(manager.remove_object(handle,&removed)!=
       dh2::object_manager_runtime_owner_v1::Status::ok)return false;
 }
}
 for(auto& faery:faeries) {
  if(prince_character.faery_character_420_for(prince_character.identity())==
      faery.identity) {
   std::string link_error;
   if(!prince_character.set_faery_character_420(
       prince_character.identity(),0,link_error))return false;
  }
  if(!retire_authored_faery_char_ai(faery))return false;
  release_authored_faery_visual(faery,program!=0);
  faery.record=nullptr;
 }
 if(character_factory&&character_factory->size()!=0)return false;
 character_factory.reset();
 source_move_in_zones.clear();
 faeries.clear();actors.clear();actor_records.clear();source_handles.clear();player_identity=0;
 assets=nullptr;
 enrolled_characters=0;module_owner=nullptr;room_zones_enabled=false;
 return true;
}

