// Source visibility follows SetVisible(false/true). This fresh-MGP slice
// starts with the ObjectBase constructor enabled byte1; disable/serialized
// enable producers and complete AI/Lua ownership remain external.
struct SpawnOwner {
 dh2::character::Coordinator character;
 ObjectActor* actor=nullptr;
 // Per-Character buff storage over this actor's canonical properties and the
 // Coordinator above. This mirrors CharProperties without sharing Player state.
 dh2::data::PropertyView buff_properties{};
 std::unique_ptr<dh2::character_player_buffs_v1::Owner> buffs;
 int animation_table=-1;
 dh2::character::Facts facts{};
 dh2::character::SpawnFacts spawn{};
 // Canonical Character+0x14d0 owner word used by the existing source
 // AI_SetTarget kernel. This is Character state, not a second target store.
 dh2::character::set_target::OwnerFacts target_owner{};
 // Source Character::Kill's +0x14e4 objective gate, retained with this same
 // Character owner. Its value is only readable after the Character ctor path.
 dh2::character_kill_field_14e4_v1::State kill_field_14e4{};
 // AI_SetDead fields belong to this stable Character owner; the canonical
 // dead byte remains actor.combat_state.dead and is not duplicated here.
 dh2::player_ai_death_v1::DeadFields dead_fields{};
 dh2::physical::CharacterBodyConfig config{};
 dh2::physical::NativeBody body{};
 BodyOwner body_owner;
 // Character constructor projections for the three dead-focus FX handles.
 // Monster FX creation is not wired to a VisualFXManager yet, so these remain
 // null and the source null-handle paths are safe to execute per actor.
 std::uintptr_t self_fx_1484=0,state_fx_148c=0,highlight_fx_14a0=0;
 // Stable per-actor route, native body view, and scene/root-motion owner.
 // These remain owned by the shared SpawnOwner across vector/world callbacks.
 dh2::actor::RuntimeState runtime{};
 std::vector<dh2::navigation::PathSegment> route_storage;
 dh2::scene::Scene scene;
 dh2::visual::SceneBinding visual;
 std::vector<std::vector<dh2::objects::Vertex>> render_vertices;
 dh2::character::PathToState40 path_to{};
 dh2::character::PathToServices16 path_services{};
 // Stable offline ObjectBase fields used by Character::IsRemotelyUpdated.
 // ObjectBase C1/C2 establish +0x110=-1 and +0x118=0; online mutation is
 // deliberately unsupported by this native actor owner.
 dh2::object_update_culling::Object remote_object{};
 dh2::character::CharacterControlServices16 control_services{};
 dh2::physical::CharacterOwnerBounds owner_bounds{};
 float visual_scale[3]{1,1,1};
 int sampled_clip=-1;
 bool runtime_ready=false;
 unsigned body_creations=0;
 float animation_speed=1.f;
 unsigned idle_updates=0;
 std::uint32_t control_failure_stage=0;
 bool death_completion_sent=false;
 std::uint32_t despawn_previous_flags=0;
 bool despawn_previous_flags_valid=false;
 std::uint32_t controller_forced=0;
 bool source_enabled=true,source_visible=true;
 explicit SpawnOwner(std::uint64_t id):character(id) {
  body_owner.native=&body;
  remote_object={std::uintptr_t(id),UINT32_MAX,0,0,{0,0}};
 }
 static void service(void*,dh2::character::State*,const dh2::character::Request*);
 static int controller_service(void*,const dh2::character::CharacterControlRequest32*,
                               dh2::character::CharacterControlResponse16*);
 static int buff_service(void*,dh2::data::PropertyView*,
                const dh2::character_player_buffs_v1::Request*,
                dh2::character_player_buffs_v1::Response*);
 static dh2::character::TimerRouting timer_route(void*,dh2::character::Coordinator&,
                std::int32_t,dh2::character::Timer32&,std::uint32_t);
 void initialize_runtime(const ObjectGroup&,const dh2::physical::CharacterOwnerBounds&,
                         const float* scale);
 void register_runtime_object();
 void update_runtime(const dh2::objects::Resource&,const dh2::animation::Player&,
                     int animation_ms,unsigned dt_ms,unsigned frame);
 void clear_all_aggro_toward_me_false();
 int request_path(const float* target);
 static int find_path(void*,const dh2::character::PathToRequest32*,std::uint32_t*);
 void bind(ObjectActor& owner,int table) {
  if(!owner.identity||remote_object.identity!=owner.identity||
     remote_object.remote_word_110!=UINT32_MAX||remote_object.remote_byte_118!=0)
   throw std::runtime_error("Ghost offline ObjectBase remote projection differs");
 actor=&owner;animation_table=table;
 if(!target_owner.identity){
  target_owner.identity=owner.identity;
  // Character+0xffc is the selected CharacterProperties AI row. AI_SetTarget
  // calls GetCharAIId after storing a nonnull target, even though it discards
  // that row's lookup result.
  target_owner.character_ai_id=owner.properties.resolved[1];
 }else if(target_owner.identity!=owner.identity){
  throw std::runtime_error("Spawn Character target-owner identity changed");
 }
 control_services={this,controller_service};
  character.bind({this,[](void* raw){return static_cast<SpawnOwner*>(raw)->facts;},
   {this,service},nullptr,nullptr,[](void* raw){return static_cast<SpawnOwner*>(raw)->spawn;},timer_route});
  if(!kill_field_14e4.constructor_write_seen&&
     dh2::character_kill_field_14e4_v1::character_constructor_completed(
       &kill_field_14e4,owner.identity)!=
       dh2::character_kill_field_14e4_v1::Status::complete)
   throw std::runtime_error("Spawn Character +0x14e4 constructor projection rejected its canonical owner");
  if(kill_field_14e4.character!=owner.identity||kill_field_14e4.retired)
   throw std::runtime_error("Spawn Character +0x14e4 owner changed or was retired");
  if(!buffs){
   buff_properties=dh2::data::property_view(actor_property_rules,owner.properties);
   buffs=dh2::character_player_buffs_v1::Owner::create({owner.identity,&buff_properties,
    {this,buff_service},std::uint32_t(actor_class_rows.size()),UINT32_MAX});
   if(!buffs)throw std::runtime_error("Spawn Character buff owner rejected canonical actor properties");
  }
 }
 void create_body() {
  if(!actor||!config.enabled)throw std::runtime_error("Spawn body configuration unavailable");
  // A repeated source InitPhysicalObject request replaces the prior backend
  // body while retaining the stable native owner/contact view.
  if(body.body){
   if(!body_owner.retire_character_identity())
    throw std::runtime_error("Spawn Character physical identity retirement failed before body replacement");
   actor_world.destroy(body.body);
  }
  body_owner.set_filter(config);
  body={actor_world.create_character(config,&body_owner.services),config.radius,config.pinned};
  if(!body.body)throw std::runtime_error("Spawn physical body creation failed");
  if(!body_owner.bind_character_identity(actor->identity)){
   actor_world.destroy(body.body);body={};body_owner.native=&body;
   throw std::runtime_error("Spawn Character physical identity registration failed");
  }
  ++body_creations;
  register_runtime_object();
  __android_log_print(ANDROID_LOG_INFO,"DH2Native","Spawn body ready | %s | creations %u | radius %.9g | category %x | mask %x",actor->name.c_str(),body_creations,body.radius*100.f,config.shape.category_bits,config.shape.mask_bits);
 }
};
bool NativeCharacterInventoryOwnerV1::initialize_source_monster(
        ObjectActor& owner,std::string& error){
 if(inventory||source_init_equipment_attempted){
  error="Monster Character::_InitEquipment cannot create or roll a second inventory";return false;
 }
 source_init_equipment_attempted=true;
 const auto* ai=native_actor_ai_props(owner);
 const auto active=source_level_owner.snapshot();
 if(owner.kind!=1||!owner.identity||owner.identity==prince_character.identity()||
    !ai||ai->script!="monster"||!owner.spawn_owner||!owner.native_ai||
    owner.spawn_owner->actor!=&owner||owner.spawn_owner->character.owner()!=owner.identity||
    owner.native_ai->character_identity!=owner.identity||native_host.online||
    active.phase!=dh2::source_level_owner_v1::Phase::active||
    active.renderer_projection!=&level||!prince_combat.inventory_loot_tables||
    !prince_combat.loot_power_creation||!prince_combat.item_power_tables||
    !prince_combat.item_presentation||!prince_combat.item_text.invoke||
    !prince_combat.item_text.metadata||native_save_difficulty<0||native_save_difficulty>2){
  error="Monster _InitEquipment requires its active canonical Character/Level and shared offline item owners";return false;
 }
 const auto property_bits=static_cast<std::uint32_t>(owner.properties.resolved[194]);
 const auto capacity_bits=(property_bits>>8)|((property_bits&0x80000000u)?0xff000000u:0u);
 std::int32_t potion_capacity=0;std::memcpy(&potion_capacity,&capacity_bits,sizeof(potion_capacity));
 if(potion_capacity<0)potion_capacity=0;
 inventory=std::make_unique<dh2::data::FreshInventoryOwnedV4>(
     owner.identity,prince_combat.inventory_loot_tables->borrow(),
     dh2::random_lifecycle::inventory_random_service(),
     static_cast<std::int8_t>(static_cast<std::uint8_t>(potion_capacity)),owner.properties);
 actor=&owner;
 adapter={prince_combat.item_text,prince_combat.item_presentation.get(),inventory.get()};
 services=adapter.inventory_services();
 property_view=dh2::data::property_view(actor_property_rules,owner.properties);
 const dh2::player_initial_equipment_v1::Bindings bindings{
     owner.identity,inventory.get(),&property_view,&services,
     {this,source_initial_equipment}};
 try{
  dh2::player_initial_equipment_v1::Runtime runtime(bindings);
  dh2::player_initial_equipment_v1::Result result{};
  if(runtime.initialize(&result,error)!=dh2::player_initial_equipment_v1::Status::complete){
   if(error.empty())error="Monster Character::_InitEquipment continuation failed";
   return false;
  }
  source_init_equipment_complete=true;
  __android_log_print(ANDROID_LOG_INFO,"DH2Native",
     "Source Monster Character::_InitEquipment | %s | Character %llx | decision %u | loot %d | items %u | auto-equip %u | canonical actor V4",
     owner.name.c_str(),static_cast<unsigned long long>(owner.identity),
     unsigned(result.decision),result.loot,result.captured_items,result.auto_equip_calls);
 }catch(const std::exception& exception){error=exception.what();return false;}
 error.clear();return true;
}
